export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "子の刻を過ぎて、師匠は休むことにした。去りぎわに、炉の火を小さく落としていった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "夜明け前の一壺は、お前が淹れろ。淹れたら、関まで提げていけ。", background: Background.Root_Act2_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "誰に？", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "まだ立っている者にだ。", background: Background.Root_Act2_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "部屋の戸が閉まった。雨は少し弱まり、叩きつける音から、ぶつぶつとこぼす声に変わった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "杯を片づけていた小満は、窓ぎわの卓に人がひとり増えているのに気づいた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸を叩く音はしなかった。閂も差したままだ。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）……裏の窓。留め金が壊れてもう半年、師匠はずっと直すって言ってたのに。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "大きな声を出さないでくれ。泥棒じゃない。この家の者だ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二階の男より、いくつか若い。ずぶ濡れの髪を無造作に後ろへかき上げ、顔にかすかな笑みを浮かべている。面白くもない冗談に、礼儀として笑ってみせるような笑みだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "腰には剣が一振り。鞘はひどく古いのに、彼の身につけているどれよりもきれいだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "君、師匠が新しく拾った子かい。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "七年。新しくない。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺からすれば新顔だよ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は立ち上がって戸の枠の前に行き、「遅」の刻み傷に手を伸ばした。指の腹が、そこで少しとまった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "へえ。俺、あの頃こんなに小さかったのか。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）私のより、頭ひとつ高いくせに。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "茶はあるかい。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "蟹眼、魚眼、急須を温め、茶葉を入れる。一煎目を捨てるとき、背後で彼が小さく笑うのが聞こえた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "まだ捨ててるのか。師匠の悪い癖だ、十年たっても直らない。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "癖じゃない。一煎目は、後に続くもののために、先に苦い思いをするの。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "……まだそれを言ってるのか、あの人。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は茶を受け取ると一息に飲みほし、熱さに顔をしかめて、杯を押し戻した。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "二階のあの人、何を背負ってた？", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "剣。油紙に包んで。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "黒い鞘で、鞘尻が欠けてる。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "見てない。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それは俺の剣だ。俺の腰にあるこれが、兄さんの。十年、互いの剣を背負ってきたんだ。笑えるだろ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）笑えない。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼はそれを見てとった。笑みが少し薄れ、それでも消えきりはしなかった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "師匠は寝た。兄さんも寝た。この家で起きてるのは君だけだ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "ひとつ話をしよう。君は数に入らないから、話せる。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "数に入らないって、どういうこと。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "話しても、話さなかったのと同じってことさ。一煎目みたいにね。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）この人、ほんとに嫌な言い方をする。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それでも、小満は離れなかった。腰を下ろした。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "十年前のあの晩、兄さんは関で白鷺門の門主の息子と剣を交えた。相手が負けると、兄さんは剣を納めてそのまま去った。振り返りもしなかった。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺は後ろで見ていた。そいつは立ち上がって、また座りこんで、それきり動かなくなった。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "駆け寄ったときには、もう血が石の隙間に染みこんでいた。兄さんのあの一突きは、深すぎたんだ。本人は知らない。あの人は昔から、自分の剣がどれほど重いか知らないんだよ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "軒から、しずくがひとつ、またひとつ落ちる。数えられるほどの間をおいて。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "白鷺門の連中は傷を読む。あの幅なら、ひと目でどの剣かわかる。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "あの年、兄さんは二十で、師匠はこの茶館を兄さんに譲ると言ったばかりだった。俺は十七で、何も持っていなかった。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "だから俺が兄さんの剣を持ち出して、自分のを置いて、戸口にあの言葉を刻んだ。それだけさ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "……それだけ？", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それだけ。白鷺門には十年追われたよ。まあ公平さ、俺のほうが足は速い。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "じゃあ、夜明けには――", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "夜明けには、兄さんが勝つ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "明日は晴れるよ、とでも言うような、軽い口ぶりだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "白鷺門が欲しいのは、死んだ下手人だ。兄さんが俺を斬れば、あの件は兄さんの手で片がつく。向こうは温家に借りまでできる。兄さんはここへ戻って、この茶館を継げばいい。きれいな身のままでね。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "師匠も年だ。誰かがここで湯を沸かさなきゃならない。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "本人に話せばいいのに。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "話したら、兄さんが背負うことになる。あの人は他人の過ちまで自分で抱えこむ人だ。まして本当に自分のものなら、なおさらさ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺は十年背負って、もう慣れた。肩のほうが、すっかりこの形になっちまった。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は空の杯をくるりと一回しして、口を下にして卓に伏せた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "君は、茶を注いでくれればそれでいい。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それから、夜明けに一煎目を捨てるとき、口をへの字にしないでくれよ。", background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は壁にもたれて目を閉じた。本当に眠れるとでもいうように。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）一煎目。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）あれは、この人のことだったんだ。", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
];
